            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | teeBotMetadata: delimited}
            parse_key_value(rest, msg)

          <<"\x80\x01", 0::1, varint_value::7, rest::binary>> ->
            value = WAWebProtobufsE2E.WebLinkRenderConfig.decode(varint_value)
            msg = %{msg | weblinkRenderConfig: value}
            parse_key_value(rest, msg)

          <<"\x80\x01", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_enum(bytes, WAWebProtobufsE2E.WebLinkRenderConfig)
            msg = %{msg | weblinkRenderConfig: value}
            parse_key_value(rest, msg)

          <<"z", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | threadID: [
                  WAWebProtobufsE2E.ThreadID.decode!(delimited) | :erlang.map_get(:threadID, msg)
                ]
            }

            parse_key_value(rest, msg)

          <<"r", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | limitSharingV2:
                  case :erlang.map_get(:limitSharingV2, msg) do
                    nil ->
                      WACommon.LimitSharing.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WACommon.LimitSharing.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"j", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | limitSharing:
                  case :erlang.map_get(:limitSharing, msg) do
                    nil ->
                      WACommon.LimitSharing.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WACommon.LimitSharing.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"b", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | supportPayload: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"X", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value != 0
            msg = %{msg | capiCreatedGroup: value}
            parse_key_value(rest, msg)

          <<"X", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_bool(bytes)
            msg = %{msg | capiCreatedGroup: value}
            parse_key_value(rest, msg)

          <<"R", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | messageAssociation:
                  case :erlang.map_get(:messageAssociation, msg) do
                    nil ->
                      WAWebProtobufsE2E.MessageAssociation.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.MessageAssociation.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"H", 0::1, varint_value::7, rest::binary>> ->
            value =
              WAWebProtobufsE2E.MessageContextInfo.MessageAddonExpiryType.decode(varint_value)

            msg = %{msg | messageAddOnExpiryType: value}
            parse_key_value(rest, msg)

          <<"H", bytes::binary>> ->
            {value, rest} =
              Protox.Decode.parse_enum(
                bytes,
                WAWebProtobufsE2E.MessageContextInfo.MessageAddonExpiryType
              )

            msg = %{msg | messageAddOnExpiryType: value}
            parse_key_value(rest, msg)

          <<"@", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | reportingTokenVersion: value}
            parse_key_value(rest, msg)

          <<"@", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_int32(bytes)
            msg = %{msg | reportingTokenVersion: value}
            parse_key_value(rest, msg)

          <<":", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | botMetadata:
                  case :erlang.map_get(:botMetadata, msg) do
                    nil ->
                      WAWebProtobufsAICommon.BotMetadata.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsAICommon.BotMetadata.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"2", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | botMessageSecret: delimited}
            parse_key_value(rest, msg)

          <<"(", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | messageAddOnDurationInSecs: value}
            parse_key_value(rest, msg)

          <<"(", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_uint32(bytes)
            msg = %{msg | messageAddOnDurationInSecs: value}
            parse_key_value(rest, msg)

          <<"\"", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | paddingBytes: delimited}
            parse_key_value(rest, msg)

          <<"\x1A", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | messageSecret: delimited}
            parse_key_value(rest, msg)

          <<"\x10", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | deviceListMetadataVersion: value}
            parse_key_value(rest, msg)

          <<"\x10", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_int32(bytes)
            msg = %{msg | deviceListMetadataVersion: value}
            parse_key_value(rest, msg)

          <<"\n", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | deviceListMetadata:
                  case :erlang.map_get(:deviceListMetadata, msg) do
                    nil ->
                      WAWebProtobufsE2E.DeviceListMetadata.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.DeviceListMetadata.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<bytes::binary>> ->
            {tag, wire_type, rest} = Protox.Decode.parse_key(bytes)
            {value, rest} = Protox.Decode.parse_unknown(tag, wire_type, rest)
            msg = %{msg | __uf__: [value | :erlang.map_get(:__uf__, msg)]}
            parse_key_value(rest, msg)
        end
      end
    )
  )

  (
    @spec unknown_fields(struct()) :: [{non_neg_integer(), Protox.Types.tag(), binary()}]
    def unknown_fields(msg), do: msg.__uf__

    @spec unknown_fields_name() :: :__uf__
    def unknown_fields_name(), do: :__uf__

    @spec clear_unknown_fields(struct) :: struct
    def clear_unknown_fields(msg), do: struct!(msg, __uf__: [])
  )

  (
    @spec default(atom()) ::
            {:ok, Protox.Scalar.scalar_default_value_type()}
            | {:error, :no_such_field | :no_default_value}
    def default(field_name), do: Protox.MessageSchema.default(@schema, field_name)
  )
end
